import sys

# Increase recursion depth just in case, though we use iterative approach
sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin
    # Using sys.stdin.read().split() handles whitespace and newlines automatically
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    if len(input_data) < 3:
        return

    N = int(input_data[0])
    S = input_data[1]
    T = input_data[2]

    # Map char index (0-25) to target char index
    # -1 if the character is not present in S
    target = [-1] * 26
    present = [False] * 26

    # Mark present characters in S
    for char in S:
        present[ord(char) - ord('a')] = True

    # Build mapping and check consistency
    # If S[i] maps to different characters in T, it's impossible
    for i in range(N):
        u = ord(S[i]) - ord('a')
        v = ord(T[i]) - ord('a')

        if target[u] != -1:
            if target[u] != v:
                print("-1")
                return
        else:
            target[u] = v

    # Count edges (u -> v where u != v)
    # Each such edge requires at least one operation
    edge_count = 0
    for u in range(26):
        if target[u] != -1:
            if target[u] != u:
                edge_count += 1

    # Detect cycles in the functional graph defined by target mapping
    # Nodes are characters 0-25. Edges are u -> target[u].
    visited = [0] * 26 # 0: unvisited, 1: visiting, 2: visited
    cycle_count = 0

    for u in range(26):
        if target[u] == -1:
            continue
        if visited[u] != 0:
            continue

        path = []
        curr = u
        # Traverse the path
        while curr != -1 and visited[curr] == 0:
            visited[curr] = 1
            path.append(curr)
            curr = target[curr]

        if curr != -1:
            if visited[curr] == 1:
                # Cycle detected. curr is a node currently in the recursion stack (path).
                # Find where the cycle starts in the path.
                try:
                    idx = path.index(curr)
                    cycle_len = len(path) - idx
                    # We only care about cycles of length >= 2
                    if cycle_len > 1:
                        cycle_count += 1
                except ValueError:
                    pass
            # If visited[curr] == 2, we merged into an already processed component, no new cycle.

        # Mark path nodes as fully visited (2)
        for node in path:
            visited[node] = 2

    # Check for spare character (a character not present in S)
    # A spare character is needed to break cycles of length >= 2
    spare = False
    for c in range(26):
        if not present[c]:
            spare = True
            break

    # Calculate answer
    # If there are cycles of length >= 2, we need 1 extra operation per cycle to break it,
    # provided we have a spare character.
    if cycle_count > 0:
        if spare:
            ans = edge_count + cycle_count
        else:
            ans = -1
    else:
        ans = edge_count

    print(ans)

if __name__ == '__main__':
    solve()

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # Precompute ways table
        # ways[len][sum] stores the number of sequences of length 'len' 
        # with digits 0-9 that sum to 'sum'.
        max_len = 10
        max_sum = 90
        ways = [[0] * (max_sum + 1) for _ in range(max_len + 1)]
        ways[0][0] = 1
        for length in range(1, max_len + 1):
            for s in range(max_sum + 1):
                val = 0
                for d in range(10):
                    if s - d >= 0:
                        val += ways[length-1][s-d]
                ways[length][s] = val

        def get_digits(n):
            if n == 0: return [0]
            digits = []
            while n > 0:
                digits.append(n % 10)
                n //= 10
            return digits[::-1]

        def count_beautiful_upto(x, s):
            if x == 0: return 0
            digits = get_digits(x)
            n = len(digits)

            memo = {}

            def dfs(index, current_sum, current_prod_mod_s, tight, started):
                if current_sum > s:
                    return 0
                if index == n:
                    return 1 if (current_sum == s and current_prod_mod_s == 0) else 0

                # Optimization: if tight is False, started is True, and product is divisible by s
                # Then any suffix with correct sum will result in a beautiful number.
                if not tight and started and current_prod_mod_s == 0:
                    rem_len = n - index
                    rem_sum = s - current_sum
                    if rem_sum < 0 or rem_sum > 9 * rem_len:
                        return 0
                    if rem_sum == 0:
                        return 1
                    else:
                        return ways[rem_len][rem_sum]

                if not tight:
                    state = (index, current_sum, current_prod_mod_s, started)
                    if state in memo:
                        return memo[state]

                limit = digits[index] if tight else 9
                res = 0

                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = current_sum + d
                    if new_sum > s:
                        continue

                    if not started:
                        if d == 0:
                            new_started = False
                            new_prod = 0
                        else:
                            new_started = True
                            new_prod = d % s
                    else:
                        new_started = True
                        if d == 0:
                            new_prod = 0
                        else:
                            new_prod = (current_prod_mod_s * d) % s

                    res += dfs(index + 1, new_sum, new_prod, new_tight, new_started)

                if not tight:
                    memo[state] = res
                return res

            return dfs(0, 0, 0, True, False)

        def count_beautiful(x):
            if x == 0: return 0
            total = 0
            # Max possible sum for a number <= x is 9 * number of digits
            # For x < 10^9, max digits is 9, so max sum is 81.
            max_s = 9 * len(str(x))
            if max_s > 90: max_s = 90

            for s in range(1, max_s + 1):
                total += count_beautiful_upto(x, s)
            return total

        return count_beautiful(r) - count_beautiful(l - 1)

import sys

# Increase recursion depth just in case
sys.setrecursionlimit(2000)

def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        p = int(next(iterator))
    except StopIteration:
        return

    A = []
    for _ in range(N):
        row = []
        for _ in range(N):
            row.append(int(next(iterator)))
        A.append(row)

    # Case p=2
    # If p=2, A_{i,j} \in {0, 1}.
    # Zeros in A are replaced by 1. Non-zeros are 1.
    # So B is the all-1s matrix.
    # B^2 = N * J (matrix of all Ns).
    # Result modulo 2 is N % 2.
    if p == 2:
        val = N % 2
        for _ in range(N):
            print(" ".join([str(val)] * N))
        return

    # Count zeros K
    K = 0
    for r in range(N):
        for c in range(N):
            if A[r][c] == 0:
                K += 1

    # Correction factor C = (-1)^K mod p
    # Derived from summing x^{p-1} over x \in F_p^* which is -1.
    # If there are K variables, and we sum over all of them, 
    # the factor is (-1) * (-1)^{K-1} = (-1)^K.
    if K % 2 == 0:
        C = 1
    else:
        C = p - 1

    # Matrix multiplication modulo p
    def mat_mul(X, Y, mod, n):
        Z = [[0] * n for _ in range(n)]
        for i in range(n):
            row_x = X[i]
            row_z = Z[i]
            for k in range(n):
                val = row_x[k]
                if val:
                    row_y = Y[k]
                    for j in range(n):
                        row_z[j] += val * row_y[j]
            for j in range(n):
                row_z[j] %= mod
        return Z

    # Matrix power
    def mat_pow(X, exp, mod, n):
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = 1
        base = X
        while exp > 0:
            if exp % 2 == 1:
                res = mat_mul(res, base, mod, n)
            base = mat_mul(base, base, mod, n)
            exp //= 2
        return res

    # Compute A^p mod p
    # This computes the sum of products of edges for all paths of length p
    # considering 0s as 0 (constant 0).
    R = mat_pow(A, p, p, N)

    # Self-loop Leave correction
    # Paths of form u -> u -> ... -> u -> v (length p)
    # Uses (u,u) p-1 times and (u,v) 1 time.
    # Requires A[u][u] == 0 (variable) and A[u][v] != 0 (constant).
    # Contribution is C * A[u][v].
    for u in range(N):
        if A[u][u] == 0:
            row_u = A[u]
            row_R_u = R[u]
            for v in range(N):
                val = row_u[v]
                if val != 0:
                    row_R_u[v] = (row_R_u[v] + C * val) % p

    # Self-loop Enter correction
    # Paths of form s -> u -> u -> ... -> u (length p)
    # Uses (s,u) 1 time and (u,u) p-1 times.
    # Requires A[s][u] != 0 (constant) and A[u][u] == 0 (variable).
    # Contribution is C * A[s][u].
    for u in range(N):
        if A[u][u] == 0:
            for s in range(N):
                val = A[s][u]
                if val != 0:
                    R[s][u] = (R[s][u] + C * val) % p

    # Back-and-forth correction (only for p=3)
    # Paths of form u -> v -> u -> v (length 3)
    # Uses (u,v) twice and (v,u) once.
    # Requires A[u][v] == 0 (variable) and A[v][u] != 0 (constant).
    # Contribution is C * A[v][u].
    if p == 3:
        for u in range(N):
            row_A_u = A[u]
            row_R_u = R[u]
            for v in range(N):
                if row_A_u[v] == 0:
                    val = A[v][u]
                    if val != 0:
                        row_R_u[v] = (row_R_u[v] + C * val) % p

    # Print result
    for row in R:
        print(" ".join(map(str, row)))

if __name__ == '__main__':
    solve()
